uint256 y = st.safeMul(lt).safeDiv(10000).safeSub(e).safeSub(1);
if (x > y) {x = y;}
IAAVE(aave).borrow(weth, x, 2, 0, address(this));
IWETH(weth).withdraw(IERC20(weth).balanceOf(address(this)));

{
