uint256 x = (e.safeMul(10000).safeSub(st.safeMul(mlr))).safeDiv(uint256(10000).safeSub(mlr));

uint256 loan_amount = x.safeMul(getDebt()).safeDiv(getCollecteral());
address[] memory tokens = new address[](1);
