IERC20(lido).safeApprove(aave, lido_bal);
IAAVE(aave).deposit(lido, lido_bal, address(this), 0);

uint256 to_repay = amount.safeAdd(fee_amount);
IAAVE(aave).borrow(weth, to_repay, 2, 0, address(this));
